export async function runMotionTossSmoke(page){
 const viewport=page.viewport(),previous=await page.evaluate(()=>({project:JSON.stringify(project),curPage,curSec,curEl,curPane,selection,secFocus,mode:NAGWEB_STORY_EDITOR.canvasMode(),timeline:NAGWEB_STORY_TIMELINE_UI.state()}));let revision=0;
 async function ready(count=8){await page.waitForFunction(count=>{const d=document.querySelector('.nw-motion-dialog iframe')?.contentDocument;return d?.querySelectorAll('.nw-toss-card').length===count&&d.defaultView.__NAG_SCROLL_DIRECTOR?.[d.querySelector('.sc')?.dataset.id]&&d.querySelector('[data-motion-canvas]')&&Array.from(d.querySelectorAll('[data-nw-stream-slot] img')).every(n=>n.complete&&n.naturalWidth>0);},{timeout:15000},count);}
 async function change(selector,value,count=8){const mark='toss-'+(++revision);await page.$eval(selector,(n,{value,mark})=>{document.querySelector('.nw-motion-dialog iframe').contentDocument.body.dataset.tossOld=mark;if(n.type==='checkbox')n.checked=value;else n.value=value;n.dispatchEvent(new Event('change',{bubbles:true}));},{value,mark});await page.waitForFunction(mark=>{const d=document.querySelector('.nw-motion-dialog iframe')?.contentDocument;return d?.body&&d.body.dataset.tossOld!==mark&&d.querySelector('.nw-toss-card');},{timeout:10000},mark);await ready(count);}
 async function pose(progress,selector='.nw-motion-dialog iframe',gid){return page.$eval(selector,(f,{progress,gid})=>{const d=f.contentDocument,id=gid||d.querySelector('.sc').dataset.id;f.contentWindow.__NAG_SCROLL_DIRECTOR[id].set(progress);return Array.from(d.querySelectorAll('[data-nw-stream-slot]'),n=>({id:n.dataset.id,src:n.querySelector('img').getAttribute('src'),phase:n.dataset.nwStreamPhase,surface:n.__nwMotionSurface,alpha:+n.querySelector('canvas').style.opacity,left:n.style.left,top:n.style.top,width:n.style.width,height:n.style.height}));},{progress,gid});}
 async function actualScroll(selector,gid){await page.$eval(selector,f=>f.contentWindow.scrollTo(0,f.contentDocument.querySelector('.sc').offsetHeight/2-f.contentWindow.innerHeight/2));await page.waitForFunction(({selector,gid})=>document.querySelector(selector).contentWindow.__NAG_SCROLL_DIRECTOR[gid].progress()>.4,{},{selector,gid});const middle=await page.$eval(selector,(f,gid)=>({p:f.contentWindow.__NAG_SCROLL_DIRECTOR[gid].progress(),phase:+f.contentDocument.querySelector('[data-nw-stream-slot]').dataset.nwStreamPhase}),gid);assert.ok(Math.abs(middle.phase-(middle.p*100-20)/60*3)<.001);await page.$eval(selector,f=>f.contentWindow.scrollTo(0,0));await page.waitForFunction(({selector,gid})=>document.querySelector(selector).contentWindow.__NAG_SCROLL_DIRECTOR[gid].progress()<.05,{},{selector,gid});assert.equal(await page.$eval(selector,f=>f.contentDocument.querySelector('[data-nw-stream-slot]').dataset.nwStreamPhase),'0.000000');}
 async function exported(gid){await page.evaluate(()=>{document.querySelector('#toss-export')?.remove();const f=document.createElement('iframe');f.id='toss-export';f.style.cssText='width:1280px;height:720px';f.srcdoc=generateSite(flattenPage(page()),false,false,false);document.body.append(f);});await page.waitForFunction(gid=>document.querySelector('#toss-export')?.contentWindow?.__NAG_SCROLL_DIRECTOR?.[gid]&&document.querySelector('#toss-export').contentDocument.querySelector('.nw-toss-card'),{},gid);}
 try{
  await page.evaluate(()=>{project.pages[0].sections=[mkSection({layout:'free',sdEnabled:false,bg:'#527467',elements:[mkEl('label',{text:'Exterior',name:'Exterior'})]})];curPage=0;curSec=0;curEl=0;selection=[];secFocus=false;saveProject();renderPane();renderPreview();history=[];future=[];});const before=await page.evaluate(()=>({project:JSON.stringify(project),stored:localStorage.getItem(STORE_KEY),outside:sec().elements[0]}));
  await page.evaluate(()=>NAGWEB_MOTION_LAB.open());await page.click('[data-motion-template="card-toss"]');await ready();assert.equal(await page.$eval('[data-motion-config="duration"]',n=>n.value),'12');assert.equal(await page.$eval('[data-motion-stream-count]',n=>[n.min,n.max].join(',')),'4,16');for(const [key,value] of [['cardSize','26'],['sizeVar','20'],['throwHeight','75'],['spread','70'],['spin','12'],['flow','staggered'],['offsetX','0'],['offsetY','0'],['backgroundType','none'],['cardRatio','3:4']])assert.equal(await page.$eval('[data-motion-stream="'+key+'"]',n=>n.value),value);
  const start=await pose(0),geometry=cards=>cards.map(({phase,...n})=>n),center=n=>({x:(n.surface[0].x+n.surface[2].x)/2,y:(n.surface[0].y+n.surface[2].y)/2}),span=n=>Math.hypot(n.surface[1].x-n.surface[0].x,n.surface[1].y-n.surface[0].y);assert.deepEqual(geometry(start),geometry(await pose(1)));const rise=(await pose(.325*.25))[0],peak=(await pose(.325*.5))[0],fall=(await pose(.325*.75))[0];assert.ok(center(rise).y>center(peak).y&&center(fall).y>center(peak).y);assert.ok(Math.abs(center(rise).y-center(fall).y)<.01);
  await change('[data-motion-stream="spin"]','0');for(const n of await pose(.1625))if(n.surface.length===4)assert.ok(Math.abs(n.surface[0].y-n.surface[1].y)<.01);await change('[data-motion-stream="sizeVar"]','0');const normal=span((await pose(.1625))[0]);await change('[data-motion-stream="cardSize"]','45');assert.ok(span((await pose(.1625))[0])>normal);await change('[data-motion-stream="cardSize"]','26');await change('[data-motion-stream="throwHeight"]','95');const high=(await pose(.1625))[0];await change('[data-motion-stream="throwHeight"]','40');assert.ok(center((await pose(.1625))[0]).y>center(high).y);await change('[data-motion-stream="throwHeight"]','75');const centered=(await pose(.1625))[0];await change('[data-motion-stream="offsetX"]','10');await change('[data-motion-stream="offsetY"]','-5');const moved=(await pose(.1625))[0];assert.ok(center(moved).x>center(centered).x&&center(moved).y<center(centered).y);await change('[data-motion-stream="offsetX"]','0');await change('[data-motion-stream="offsetY"]','0');await change('[data-motion-stream="flow"]','one');for(let i=0;i<8;i++)assert.deepEqual((await pose((i+.5)/8)).filter(n=>n.alpha>.9).map(n=>n.id),[start[i].id]);await change('[data-motion-stream="flow"]','staggered');await change('[data-motion-stream="sizeVar"]','20');await change('[data-motion-stream="spin"]','12');
  const cache=await page.$eval('.nw-motion-dialog iframe',f=>{const d=f.contentDocument,rt=f.contentWindow.__NAG_SCROLL_DIRECTOR[d.querySelector('.sc').dataset.id],native=d.createElement;let created=0;d.createElement=function(tag,...args){if(tag==='canvas')created++;return native.call(this,tag,...args);};try{for(let i=0;i<60;i++)rt.set(i/60);const warm=created;created=0;for(let i=0;i<60;i++)rt.set(i/60);return{warm,after:created};}finally{d.createElement=native;}});assert.ok(cache.warm<=8);assert.equal(cache.after,0,'Flying images retain their source textures');
  await pose(.14);await fs.mkdir('/tmp/nagweb-motion-visuals',{recursive:true});await (await page.$('.nw-motion-dialog')).screenshot({path:'/tmp/nagweb-motion-visuals/card-toss-desktop.png'});
  await change('[data-motion-stream-count]','4',4);await page.click('[data-motion-library-tab="elements"]');await page.click('[data-motion-layer="'+start[0].id+'"]');assert.equal(await page.$eval('[data-motion-element-remove]',n=>n.disabled),true);await change('[data-motion-stream-count]','8');assert.deepEqual((await pose(0)).map(n=>[n.id,n.src]),start.map(n=>[n.id,n.src]));await change('[data-motion-stream-count]','16',16);await page.click('[data-motion-layer="'+start[0].id+'"]');assert.equal(await page.$eval('[data-motion-duplicate]',n=>n.disabled),true);await change('[data-motion-stream-count]','8');await change('[data-motion-stream="throwHeight"]','90');await change('[data-motion-config="source"]','scroll');await change('[data-motion-stream="turns"]','3');await change('[data-motion-stream="start"]','20');await change('[data-motion-stream="end"]','80');await change('[data-motion-stream="scrollLength"]','420');assert.equal((await pose(.1))[0].phase,'0.000000');assert.equal((await pose(.5))[0].phase,'1.500000');assert.equal((await pose(.9))[0].phase,'3.000000');assert.deepEqual(geometry(await pose(.1)),geometry(await pose(.9)));assert.equal(await page.evaluate(()=>JSON.stringify(project)),before.project);assert.equal(await page.evaluate(()=>localStorage.getItem(STORE_KEY)),before.stored);
  await page.click('[data-motion-library-tab="library"]');await page.$eval('[data-motion-library-name]',n=>n.value='Mi secuencia');await page.click('[data-motion-library-save]');const saved=await page.evaluate(()=>project.nwMotionLibrary.at(-1));assert.equal(saved.config.stream.kind,'card-toss');assert.equal(saved.config.stream.throwHeight,90);assert.equal(saved.assets.length,8);await page.click('[data-motion-saved="'+saved.id+'"]');await ready();const copied=await pose(.35);assert.ok(copied.every(n=>!start.some(o=>o.id===n.id)));assert.deepEqual(copied.map(n=>n.src),start.map(n=>n.src));await page.click('[data-motion-insert-group]');const inserted=await page.evaluate(()=>{const g=sec().elements.find(e=>e.nwMotionInstance);return{gid:g.id,project:JSON.stringify(project),group:g,outside:sec().elements[0],length:sec().sdLength,enabled:sec().sdEnabled};});assert.equal(inserted.enabled,true);assert.equal(inserted.length,420);assert.equal(inserted.group.bg,'transparent');assert.deepEqual(inserted.outside,before.outside);await page.waitForFunction(id=>document.querySelector('#preview')?.contentWindow?.__NAG_SCROLL_DIRECTOR?.[id]&&document.querySelector('#preview').contentDocument.querySelector('.nw-toss-card'),{},inserted.gid);await actualScroll('#preview',inserted.gid);await exported(inserted.gid);assert.deepEqual((await pose(.35,'#toss-export',inserted.gid)).map(n=>n.src),copied.map(n=>n.src));await page.$eval('#toss-export',(f,id)=>f.contentWindow.__NAG_SCROLL_DIRECTOR[id].live(),inserted.gid);await actualScroll('#toss-export',inserted.gid);await page.evaluate(()=>document.querySelector('#toss-export').remove());
  await page.evaluate(id=>{NAGWEB_SCROLL_DIRECTOR.scrub(id,.25);NAGWEB_MOTION_LAB.edit(id);},inserted.gid);await ready();await change('[data-motion-stream="throwHeight"]','95');await page.$eval('#preview',f=>f.contentDocument.body.dataset.tossSaved='old');await page.click('[data-motion-save]');await page.waitForFunction(id=>{const f=document.querySelector('#preview');return f?.contentDocument?.body&&!f.contentDocument.body.dataset.tossSaved&&f.contentWindow.__NAG_SCROLL_DIRECTOR?.[id]&&f.contentDocument.querySelector('.nw-toss-card');},{},inserted.gid);await actualScroll('#preview',inserted.gid);const scroll=await page.evaluate(()=>JSON.stringify(project));
  await page.evaluate(id=>NAGWEB_MOTION_LAB.edit(id),inserted.gid);await ready();assert.equal(await page.$eval('[data-motion-stream="throwHeight"]',n=>n.value),'95');await change('[data-motion-config="source"]','time');await change('[data-motion-config="duration"]','2');await page.click('[data-motion-save]');const loop=await page.evaluate(()=>JSON.stringify(project));assert.equal(await page.evaluate(()=>sec().sdEnabled),false);await exported(inserted.gid);const clock=await page.$eval('#toss-export',(f,id)=>f.contentWindow.__NAG_SCROLL_DIRECTOR[id].progress(),inserted.gid);await page.waitForFunction(({gid,clock})=>document.querySelector('#toss-export').contentWindow.__NAG_SCROLL_DIRECTOR[gid].progress()!==clock,{timeout:3000},{gid:inserted.gid,clock});assert.equal(await page.$eval('#toss-export',f=>!!f.contentDocument.querySelector('.nw-sd-active')),false);await page.evaluate(()=>document.querySelector('#toss-export').remove());await page.evaluate(()=>undo());assert.equal(await page.evaluate(()=>JSON.stringify(project)),scroll);await page.evaluate(()=>redo());assert.equal(await page.evaluate(()=>JSON.stringify(project)),loop);assert.equal(await page.evaluate(id=>migrate(JSON.parse(JSON.stringify(project))).pages[0].sections[0].elements.find(e=>e.id===id).nwMotionInstance.stream.kind,inserted.gid),'card-toss');
  await page.setViewport({width:390,height:844,deviceScaleFactor:1});await page.evaluate(()=>NAGWEB_MOTION_LAB.open());await page.click('[data-motion-template="card-toss"]');await ready();await change('[data-motion-stream="frameRatio"]','auto');await (await page.$('.nw-motion-dialog')).screenshot({path:'/tmp/nagweb-motion-visuals/card-toss-mobile.png'});await page.emulateMediaFeatures([{name:'prefers-reduced-motion',value:'reduce'}]);assert.deepEqual(await pose(.1),await pose(.9));await page.emulateMediaFeatures([]);await page.click('[data-motion-close]');await page.setViewport(viewport);assert.equal(await page.evaluate(()=>JSON.stringify(project)),loop);await page.evaluate(()=>NAGWEB_MOTION_LAB.open());await page.click('[data-motion-template="card-toss"]');await ready();await page.click('[data-motion-insert]');const newScene=await page.evaluate(()=>({gid:sec().nwMotionSceneGroup,config:sec().elements.find(e=>e.nwMotionInstance).nwMotionInstance}));assert.equal(newScene.config.template,'card-toss');assert.ok(newScene.gid);await page.evaluate(id=>NAGWEB_MOTION_LAB.edit(id),newScene.gid);await ready();await page.click('[data-motion-close]');
  console.log('Card Toss: subida y caída, ritmos una por vez/superpuestas, altura/tamaño/dispersión/giro y posición, proporciones y texturas estables, cantidad 4–16 y recuperación, controles/borrador/Biblioteca, scroll real tras guardar, loop independiente, transparencia, historial/JSON/exportación, escena reeditable, móvil y movimiento reducido OK');
 }catch(error){await page.screenshot({path:'/tmp/nagweb-motion-visuals/card-toss-failure.png'}).catch(()=>{});throw error;}finally{await page.emulateMediaFeatures([]);await page.setViewport(viewport);await page.evaluate(p=>{document.querySelector('.nw-motion-dialog').close();document.querySelector('#toss-export')?.remove();clearTimeout(previewTimer);project=JSON.parse(p.project);curPage=p.curPage;curSec=p.curSec;curEl=p.curEl;curPane=p.curPane;selection=p.selection;secFocus=p.secFocus;history=[];future=[];NAGWEB_STORY_EDITOR.setCanvasMode(p.mode);NAGWEB_STORY_TIMELINE_UI.setState(p.timeline);saveProject();renderScenes();renderPane();renderPreview();},previous);}
}

export async function runMotionTossDepthSmoke(page){
 const previous=await page.evaluate(()=>({project:JSON.stringify(project),curPage,curSec,curEl,curPane,selection,secFocus,mode:NAGWEB_STORY_EDITOR.canvasMode(),timeline:NAGWEB_STORY_TIMELINE_UI.state()}));let revision=0;
 async function ready(count=4){await page.waitForFunction(count=>{const d=document.querySelector('.nw-motion-dialog iframe')?.contentDocument;return d?.querySelectorAll('.nw-toss-card').length===count&&d.defaultView.__NAG_SCROLL_DIRECTOR?.[d.querySelector('.sc')?.dataset.id]&&Array.from(d.querySelectorAll('[data-nw-stream-slot] img')).every(n=>n.complete&&n.naturalWidth>0);},{timeout:15000},count);}
 async function change(key,value){const mark='toss-depth-'+(++revision);await page.$eval('[data-motion-stream="'+key+'"]',(n,{value,mark})=>{document.querySelector('.nw-motion-dialog iframe').contentDocument.body.dataset.tossDepthOld=mark;if(n.type==='checkbox')n.checked=value;else n.value=value;n.dispatchEvent(new Event('change',{bubbles:true}));},{value,mark});await page.waitForFunction(mark=>{const d=document.querySelector('.nw-motion-dialog iframe')?.contentDocument;return d?.body&&d.body.dataset.tossDepthOld!==mark&&d.querySelector('.nw-toss-card');},{},mark);await ready();}
 function screenshotPixel(bytes){const png=Buffer.from(bytes),chunks=[];let channels;assert.equal(png.subarray(1,4).toString(),'PNG');for(let i=8;i<png.length;){const length=png.readUInt32BE(i),kind=png.subarray(i+4,i+8).toString(),data=png.subarray(i+8,i+8+length);if(kind==='IHDR'){assert.equal(data.readUInt32BE(0),1);assert.equal(data.readUInt32BE(4),1);assert.equal(data[8],8);assert.ok(data[9]===2||data[9]===6);channels=data[9]===2?3:4;}if(kind==='IDAT')chunks.push(data);i+=length+12;}const row=inflateSync(Buffer.concat(chunks));assert.ok(row[0]<=4);return Array.from(row.subarray(1,1+channels)).concat(channels===3?[255]:[]);}
 try{
  await page.evaluate(()=>{project.pages[0].sections=[mkSection({layout:'free',sdEnabled:false,elements:[]})];curPage=0;curSec=0;curEl=0;selection=[];secFocus=false;saveProject();renderPane();renderPreview();history=[];future=[];});await page.evaluate(()=>NAGWEB_MOTION_LAB.open());await page.click('[data-motion-template="card-toss"]');await ready(8);await page.$eval('[data-motion-stream-count]',n=>{n.value='4';n.dispatchEvent(new Event('change',{bubbles:true}));});await ready();
  for(const [key,value] of [['flow','staggered'],['spread','0'],['spin','0'],['sizeVar','0'],['cardSize','45'],['throwHeight','75'],['frameRatio','auto'],['cornerRadius','0'],['shadow',false]])await change(key,value);
  const colors=[[255,0,0],[0,255,0],[0,0,255],[255,255,0]];
  await page.$eval('[data-motion-stream-batch-upload]',(input,colors)=>{const transfer=new DataTransfer();colors.forEach((color,i)=>transfer.items.add(new File(['<svg xmlns="http://www.w3.org/2000/svg" width="300" height="300"><rect width="300" height="300" fill="rgb('+color.join(',')+')"/></svg>'],'Toss-depth-'+i+'.svg',{type:'image/svg+xml'})));input.files=transfer.files;input.dispatchEvent(new Event('change',{bubbles:true}));},colors);await page.waitForFunction(()=>/Se cargaron 4/.test(document.querySelector('[data-motion-stream-batch-status]')?.textContent||''));await ready();
  for(const progress of [.375,.625]){
   const probe=await page.$eval('.nw-motion-dialog iframe',(f,{progress,colors})=>{const d=f.contentDocument,nodes=Array.from(d.querySelectorAll('[data-nw-stream-slot]')),host=nodes[0].offsetParent;f.contentWindow.__NAG_SCROLL_DIRECTOR[d.querySelector('.sc').dataset.id].set(progress);const clip=nodes[0].__nwMotionClip,tiles=nodes.map((n,slot)=>({id:n.dataset.id,slot,polygon:n.__nwMotionSurface,visible:n.__nwMotionVisible})).filter(t=>t.visible).reverse(),inside=(poly,x,y)=>{let hit=false;for(let i=0,j=poly.length-1;i<poly.length;j=i++)if((poly[i].y>y)!==(poly[j].y>y)&&x<(poly[j].x-poly[i].x)*(y-poly[i].y)/(poly[j].y-poly[i].y)+poly[i].x)hit=!hit;return hit;};for(let y=clip.top+8;y<clip.top+clip.height-8;y+=7)for(let x=clip.left+8;x<clip.left+clip.width-8;x+=7){const hits=tiles.filter(t=>inside(t.polygon,x,y));if(hits.length<2)continue;const top=hits[0];let edge=Infinity;for(let i=0;i<4;i++){const a=top.polygon[i],b=top.polygon[(i+1)%4];edge=Math.min(edge,Math.abs((b.y-a.y)*x-(b.x-a.x)*y+b.x*a.y-b.y*a.x)/Math.hypot(b.y-a.y,b.x-a.x));}if(edge<6)continue;const fr=f.getBoundingClientRect(),hr=host.getBoundingClientRect();return{id:top.id,slot:top.slot,expected:colors[top.slot],click:{x:fr.left+(hr.left+x)*fr.width/f.clientWidth,y:fr.top+(hr.top+y)*fr.height/f.clientHeight},overlaps:hits.length};}return null;},{progress,colors});
   assert.ok(probe,'Superposed flights have a visible overlap');assert.ok(probe.overlaps>=2);const pixel=screenshotPixel(await page.screenshot({type:'png',clip:{x:Math.floor(probe.click.x),y:Math.floor(probe.click.y),width:1,height:1}}));assert.equal(pixel[3],255);for(let i=0;i<3;i++)assert.ok(Math.abs(pixel[i]-probe.expected[i])<4,JSON.stringify({probe,pixel}));await page.mouse.click(probe.click.x,probe.click.y);assert.equal(await page.$eval('[data-motion-layer="'+probe.id+'"]',n=>n.getAttribute('aria-pressed')),'true');
  }
  console.log('Card Toss superposición: píxeles reales de archivos propios y clics coinciden con la tarjeta frontal durante dos lanzamientos OK');
 }catch(error){await page.screenshot({path:'/tmp/nagweb-motion-visuals/card-toss-depth-failure.png'}).catch(()=>{});throw error;}finally{await page.evaluate(p=>{document.querySelector('.nw-motion-dialog').close();clearTimeout(previewTimer);project=JSON.parse(p.project);curPage=p.curPage;curSec=p.curSec;curEl=p.curEl;curPane=p.curPane;selection=p.selection;secFocus=p.secFocus;history=[];future=[];NAGWEB_STORY_EDITOR.setCanvasMode(p.mode);NAGWEB_STORY_TIMELINE_UI.setState(p.timeline);saveProject();renderScenes();renderPane();renderPreview();},previous);}
}
